/* Generated local-safe train frame asset bundle. Source PNGs remain in assets/. */
(function () {
  "use strict";
  var assets = {
    recordDividerV1: "data:image/png;base64,",
    couponDivider: "data:image/png;base64,",
    mainOpening: "data:image/png;base64,",
    backOpening: "data:image/png;base64,",
    main: "data:image/png;base64,",
    back: "data:image/png;base64,",
    stub: "data:image/png;base64,",
    backImageFrame: "data:image/png;base64,",
  };
  window.LOG_TICKET_TRAIN_FRAME_ASSETS = assets;
  window.LOG_TICKET_TRAIN_MAIN_OPENING_MASK_ASSET = assets.mainOpening;
  window.LOG_TICKET_TRAIN_BACK_OPENING_MASK_ASSET = assets.backOpening;
  var variantCache = {};
  var latestRequest = "";

  function safeColor(value) {
    var normalized = String(value || "").trim().toLowerCase();
    return /^#[0-9a-f]{6}$/.test(normalized) ? normalized : "#355a58";
  }

  function renderVariant(assetKey, color, variant) {
    var cacheKey = [assetKey, color, variant].join("|");
    if (variantCache[cacheKey]) return variantCache[cacheKey];
    variantCache[cacheKey] = new Promise(function (resolve, reject) {
      var sourceImage = new Image();
      sourceImage.onload = function () {
        var width = sourceImage.naturalWidth;
        var height = sourceImage.naturalHeight;
        var tinted = document.createElement("canvas");
        tinted.width = width;
        tinted.height = height;
        var tintedContext = tinted.getContext("2d");
        tintedContext.drawImage(sourceImage, 0, 0);
        tintedContext.globalCompositeOperation = "source-in";
        tintedContext.fillStyle = color;
        tintedContext.fillRect(0, 0, width, height);
        tintedContext.globalCompositeOperation = "source-over";

        var dataUrl = tinted.toDataURL("image/png");
        tinted.width = tinted.height = 1;
        resolve(dataUrl);
      };
      sourceImage.onerror = function () { reject(new Error("Train frame artwork could not be decoded.")); };
      sourceImage.src = assets[assetKey];
    });
    return variantCache[cacheKey];
  }

  function tintSource(source, color) {
    color = safeColor(color);
    var cacheKey = ["source", source, color].join("|");
    if (variantCache[cacheKey]) return variantCache[cacheKey];
    variantCache[cacheKey] = new Promise(function (resolve, reject) {
      var sourceImage = new Image();
      sourceImage.onload = function () {
        var tinted = document.createElement("canvas");
        tinted.width = sourceImage.naturalWidth;
        tinted.height = sourceImage.naturalHeight;
        var context = tinted.getContext("2d");
        context.drawImage(sourceImage, 0, 0);
        context.globalCompositeOperation = "source-in";
        context.fillStyle = color;
        context.fillRect(0, 0, tinted.width, tinted.height);
        context.globalCompositeOperation = "source-over";
        var dataUrl = tinted.toDataURL("image/png");
        tinted.width = tinted.height = 1;
        resolve(dataUrl);
      };
      sourceImage.onerror = function () { reject(new Error("Train frame artwork could not be decoded.")); };
      sourceImage.src = source;
    });
    return variantCache[cacheKey];
  }

  function assignSources(sources, requestKey) {
    if (requestKey !== latestRequest) return;
    document.querySelectorAll('img[data-frame-asset="main"]').forEach(function (image) { if (image.src !== sources.main) image.src = sources.main; });
    document.querySelectorAll('img[data-frame-asset="stub"]').forEach(function (image) {
      var source = image.closest(".ticket-back") ? sources.stubBack : sources.stubFront;
      if (image.src !== source) image.src = source;
    });
    document.querySelectorAll('img[data-frame-asset="stub-divider"]').forEach(function (image) {
      var source = image.closest(".ticket-back") ? sources.dividerBack : sources.dividerFront;
      if (image.src !== source) image.src = source;
    });
    document.querySelectorAll('img[data-frame-asset="record-divider-top"]').forEach(function (image) { if (image.src !== sources.recordDividerTop) image.src = sources.recordDividerTop; });
    document.querySelectorAll('img[data-frame-asset="back-image-frame"]').forEach(function (image) { if (image.src !== sources.backImageFrame) image.src = sources.backImageFrame; });
  }

  function applyFrameColor(input) {
    var colors = typeof input === "object" && input ? {
      mainFront: safeColor(input.mainFront), mainBack: safeColor(input.mainBack),
      stubFront: safeColor(input.stubFront), stubBack: safeColor(input.stubBack),
      dividerFront: safeColor(input.dividerFront), dividerBack: safeColor(input.dividerBack),
      recordDividerTop: safeColor(input.recordDividerTop), recordDividerMiddle: safeColor(input.recordDividerMiddle),
      backImageFrame: safeColor(input.backImageFrame)
    } : {
      mainFront: safeColor(input), mainBack: safeColor(input), stubFront: safeColor(input),
      stubBack: safeColor(input), dividerFront: safeColor(input), dividerBack: safeColor(input),
      recordDividerTop: safeColor(input), recordDividerMiddle: safeColor(input), backImageFrame: safeColor(input)
    };
    var requestKey = JSON.stringify(colors);
    latestRequest = requestKey;
    return Promise.all([
      renderVariant("main", colors.mainFront, "full"),
      renderVariant("stub", colors.stubFront, "full"), renderVariant("stub", colors.stubBack, "full"),
      renderVariant("couponDivider", colors.dividerFront, "full"), renderVariant("couponDivider", colors.dividerBack, "full"),
      renderVariant("recordDividerV1", colors.recordDividerTop, "full"),
      renderVariant("backImageFrame", colors.backImageFrame, "full")
    ]).then(function (results) {
      assignSources({ main: results[0], stubFront: results[1], stubBack: results[2], dividerFront: results[3], dividerBack: results[4], recordDividerTop: results[5], backImageFrame: results[6] }, requestKey);
    });
  }

  window.LOG_TICKET_TRAIN_FRAME_RENDERER = { apply: applyFrameColor, tintSource: tintSource };
  function hydrateTrainFrames() {
    document.querySelectorAll("img[data-frame-asset]").forEach(function (image) {
      var key = image.getAttribute("data-frame-asset");
      var assetKey = key === "stub-divider" ? "couponDivider" : key.indexOf("record-divider-") === 0 ? "recordDividerV1" : key === "back-image-frame" ? "backImageFrame" : key;
      var source = assets[assetKey];
      if (source && image.src !== source) image.src = source;
    });
    applyFrameColor("#355a58");
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", hydrateTrainFrames, { once: true });
  } else {
    hydrateTrainFrames();
  }
})();
